-- public.taste_says(p_world uuid, it item)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.taste_says(p_world uuid, it item)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare d item_def; v_said text[] := '{}'; v_feeds text[]; v_skill text;
begin
  select * into d from item_def where id = it.def;
  if not found or (coalesce(d.food, 0) = 0 and coalesce(d.drink, 0) = 0) then return ''; end if;
  v_said := v_said || case when coalesce(d.food, 0) > 0
    then 'food bar +' || whole_pct(d.food::double precision * (0.7 + it.ql::double precision / 200) * mark_of(it.mark, 'fill'))
    else 'thirst bar +' || whole_pct(coalesce(d.drink, 0)::double precision) end;
  select array_agg(f.nutrient || ' +' || whole_pct(f.amount::double precision * helping_of(it.ql) * mark_of(it.mark, 'feed'))
                   order by array_position(array['starch', 'flesh', 'fat', 'greens'], f.nutrient))
    into v_feeds
    from item_feeds f where f.item = it.def and f.amount > 0;
  if v_feeds is not null then v_said := v_said || v_feeds; end if;
  v_skill := knack_says(it.def);
  if v_skill <> '' then
    v_said := v_said || (lower(left(v_skill, 1)) || substr(v_skill, 2) || ', ' || clock_left(boon_time(it.def, it.ql, mark_of(it.mark, 'knack'))));
  end if;
  return ' Per helping: ' || array_to_string(v_said, ', ') || '.';
end $function$
